steps.script:
var u = GameState.state.units['U_ALLARUS_CUSTODIANS_A_P2']
var c = Vector2.ZERO
for m in u.models:
	c += Vector2(m.position.x, m.position.y)
c /= u.models.size()
var d = Vector2(950, 560) - c
for m in u.models:
	m.position = {'x': m.position.x + d.x, 'y': m.position.y + d.y}
tree.current_scene._recreate_unit_visuals()
return true

var a = GameState.state.units['U_PROSECUTORS_A']
var b = GameState.state.units['U_CUSTODIAN_GUARD_F']
var ca = Vector2.ZERO
for m in a.models:
	ca += Vector2(m.position.x, m.position.y)
ca /= a.models.size()
var cb = Vector2.ZERO
for m in b.models:
	cb += Vector2(m.position.x, m.position.y)
cb /= b.models.size()
var da = Vector2(700, 470) - ca
var db = Vector2(300, 700) - cb
for m in a.models:
	m.position = {'x': m.position.x + da.x, 'y': m.position.y + da.y}
for m in b.models:
	m.position = {'x': m.position.x + db.x, 'y': m.position.y + db.y}
AIDecisionMaker.load_player_profile(1, {'parameters': {'THREAT_TARGET_SPLIT': 0.0}, 'rules': []})
tree.current_scene._recreate_unit_visuals()
return true

var pnl = tree.current_scene._ai_suggestion_panel
for r in range(3):
	for c in range(8):
		pnl._expanded['opt:%d:%d' % [r, c]] = true
pnl._render(false)
var t = pnl._rich.get_parsed_text()
pnl._rich.scroll_to_line(t.substr(0, t.find('All options')).count('\n'))
return t.contains('Hold obj_home_1')
